/**
 * ODFlow — Stop & Ridership Module
 * Draws the bus-stop layer and the stop-detail panel on the left of the map.
 *
 * Every figure comes from data/stops.json, generated by
 * apps/backend/scripts/build_dashboard_data.py out of the תלת״ן station survey
 * (boardings, calls, transfer share, rider split) joined to GTFS for the line
 * numbers. Nothing here invents a number: a station the survey never covered
 * renders as "no survey data", never as zero.
 *
 * Depends on: Leaflet `map` global and `state`/`pointInArea` from app.js.
 */

// Display labels for the survey's own rider-type column names. The ids come from
// the data; only their Hebrew wording lives here, and an id with no label falls
// through to the raw column name rather than being dropped.
const RIDER_LABELS = {
  ADULT: 'בוגר', YOUTH: 'נוער', ELDERLY: 'קשיש',
  STUDENT: 'סטודנט', DISABLED: 'נכה', OTHER: 'אחר',
};

// Sequential single-hue ramps — boardings are a magnitude, so one hue (the
// brand teal), ordered low-to-high so "more" always reads as "stronger" on the
// surface in use: brightening against the dark basemap, darkening against the
// light one. Both directions were validated for monotonic lightness, visible
// gaps between steps, and a low end that still separates from the basemap.
const STOP_RAMP = {
  dark: ['#115e59', '#0f766e', '#0d9488', '#14b8a6', '#5eead4'],
  light: ['#14b8a6', '#0d9488', '#0f766e', '#115e59', '#0b3d39'],
};

const SS = {
  data: null,            // loaded lazily from data/stops.json
  loading: false,
  layer: L.layerGroup(),
  markers: new Map(),    // station code+coords key → marker
  selected: null,        // station currently shown in the panel
  breaks: [],            // colour-class upper bounds, recomputed from the visible stations
  visible: [],           // stations passing the current neighbourhood filter
};

function stopKey(s) { return `${s.code}@${s.lat},${s.lon}`; }
function isLightTheme() { return document.body.classList.contains('light-theme'); }
function stopRamp() { return isLightTheme() ? STOP_RAMP.light : STOP_RAMP.dark; }

function fmtNum(n, digits = 0) {
  if (n == null) return '—';
  return (+n).toLocaleString('he-IL', { minimumFractionDigits: digits, maximumFractionDigits: digits });
}

// ── Scales, derived from the data actually on screen ──────────────────────────

// Quantile classes: five bins holding a similar number of stations each. Boardings
// are heavily skewed (a central terminal carries orders of magnitude more than a
// side street), so equal-width bins would put almost every station in the lowest
// colour and waste the ramp.
function computeBreaks(stations) {
  const vals = stations.map(s => s.boardings_day).filter(v => v != null).sort((a, b) => a - b);
  if (!vals.length) return [];
  const ramp = stopRamp();
  return Array.from({ length: ramp.length - 1 },
    (_, i) => vals[Math.floor(vals.length * (i + 1) / ramp.length)]);
}

function stopColor(v) {
  if (v == null) return null;                 // not surveyed — drawn as a hollow ring
  const ramp = stopRamp();
  let i = 0;
  while (i < SS.breaks.length && v > SS.breaks[i]) i++;
  return ramp[i];
}

// Radius by square root of boardings, so the *area* of the circle is proportional
// to the value — scaling the radius directly would exaggerate the busy stops.
function stopRadius(v, max) {
  if (v == null || !max) return 3;
  return 3.5 + 9 * Math.sqrt(v / max);
}

// ── Loading ───────────────────────────────────────────────────────────────────

async function ensureStops() {
  if (SS.data || SS.loading) { renderStops(); return; }
  SS.loading = true;
  try {
    const r = await fetch('./data/stops.json');
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
    SS.data = await r.json();
    renderStops();
    updateStopsKpi();
  } catch (e) {
    console.error('[Stops] failed to load stops.json:', e);
  } finally {
    SS.loading = false;
  }
}

// ── Map layer ─────────────────────────────────────────────────────────────────

function renderStops() {
  if (!SS.data) return;
  SS.layer.clearLayers();
  SS.markers.clear();

  // Same area rule the speed and destination layers use.
  SS.visible = SS.data.stations.filter(
    s => !state.areaFilter || pointInArea(s.lat, s.lon, state.areaFilter)
  );
  SS.breaks = computeBreaks(SS.visible);
  const max = SS.visible.reduce((m, s) => Math.max(m, s.boardings_day || 0), 0);
  // Un-surveyed stops stay hollow; surveyed ones get a hairline in the basemap's
  // own colour so overlapping dots stay countable.
  const ring = isLightTheme() ? '#94a3b8' : '#64748b';
  const edge = isLightTheme() ? '#ffffff' : '#0b0b0b';

  for (const s of SS.visible) {
    const fill = stopColor(s.boardings_day);
    const marker = L.circleMarker([s.lat, s.lon], {
      pane: 'pointPane',
      radius: stopRadius(s.boardings_day, max),
      color: fill ? edge : ring,
      weight: fill ? 1 : 1.5,
      fillColor: fill || 'transparent',
      fillOpacity: fill ? 0.9 : 0,
    });
    marker.bindTooltip(
      `<div dir="rtl" style="text-align:right"><b>${s.name}</b><br>` +
      (s.boardings_day != null
        ? `${fmtNum(s.boardings_day)} עליות ביום`
        : 'ללא נתוני סקר') +
      '</div>',
      { direction: 'top', opacity: 0.95 }
    );
    marker._stroke = fill ? edge : ring;
    marker._weight = fill ? 1 : 1.5;
    marker.on('click', () => selectStop(s));
    marker.addTo(SS.layer);
    SS.markers.set(stopKey(s), marker);
  }

  if (SS.selected) highlightSelected();
  renderStopsLegend();
}

// The selected stop is ringed in the ink colour rather than a brand hue — the
// ramp already owns teal, so a teal halo on a teal dot would read as "busier".
function highlightSelected() {
  const sel = isLightTheme() ? '#0f1f3e' : '#ffffff';
  for (const [key, m] of SS.markers) {
    const on = SS.selected && key === stopKey(SS.selected);
    m.setStyle({ color: on ? sel : m._stroke, weight: on ? 2.5 : m._weight });
    if (on) m.bringToFront();
  }
}

function renderStopsLegend() {
  const wrap = document.getElementById('stopsLegend');
  if (!wrap || !SS.data) return;
  const ramp = stopRamp();
  const surveyed = SS.visible.filter(s => s.boardings_day != null).length;

  // Ranges are printed from the computed breaks, so the legend can never describe
  // a classification the map isn't using.
  const rows = ramp.map((c, i) => {
    const lo = i === 0 ? 0 : SS.breaks[i - 1];
    const hi = i < SS.breaks.length ? SS.breaks[i] : null;
    const label = hi == null ? `${fmtNum(lo)}+` : `${fmtNum(lo)}–${fmtNum(hi)}`;
    return `<div class="lg"><span style="background:${c}"></span> ${label}</div>`;
  }).join('');

  wrap.innerHTML = `
    <div class="stops-legend-title">עליות ליום · ${fmtNum(surveyed)} תחנות עם נתוני סקר</div>
    ${rows}
    <div class="lg"><span class="lg-hollow"></span> ללא נתוני סקר</div>
    <div class="stops-legend-note">גודל העיגול ביחס למספר העליות</div>`;
}

// ── Stop detail panel ─────────────────────────────────────────────────────────

function selectStop(station) {
  SS.selected = station;
  highlightSelected();
  renderPanel();
}

function closeStopPanel() {
  SS.selected = null;
  highlightSelected();
  const panel = document.getElementById('stopPanel');
  if (panel) panel.style.display = 'none';
}

// Share of a whole, as a percentage of the parts actually reported — the rider-type
// columns sum to slightly less than ONDAY (the survey's own daily total), so
// dividing by ONDAY would quietly lose a few percent off every station.
function shares(values) {
  const total = values.reduce((a, b) => a + b, 0);
  return total > 0 ? values.map(v => v / total * 100) : values.map(() => 0);
}

function bandChart(bands, values, unit) {
  const max = Math.max(...values);
  const peak = values.indexOf(max);
  const ramp = stopRamp();
  // Seven bars share ~300px, so a city-wide figure like 134,933 would collide with
  // its neighbours. Above five digits the labels switch to compact form; the exact
  // value stays one hover away.
  const label = max >= 10000
    ? v => (+v).toLocaleString('he-IL', { notation: 'compact', maximumFractionDigits: 1 })
    : v => fmtNum(v);
  const cells = values.map((v, i) => {
    const h = max > 0 ? Math.max(2, Math.round(v / max * 46)) : 2;
    const share = max > 0 ? (v / values.reduce((a, b) => a + b, 0) * 100) : 0;
    return `
      <div class="band ${i === peak ? 'peak' : ''}" title="${bands[i]} · ${fmtNum(v, 1)} ${unit} (${share.toFixed(0)}%)">
        <div class="band-val">${label(v)}</div>
        <div class="band-bar" style="height:${h}px;background:${i === peak ? ramp[ramp.length - 1] : ramp[2]}"></div>
        <div class="band-lbl">${bands[i]}</div>
      </div>`;
  }).join('');
  return `<div class="bands">${cells}</div>`;
}

function riderChart(types, values) {
  const pct = shares(values);
  const rows = types
    .map((t, i) => ({ label: RIDER_LABELS[t] || t, pct: pct[i], value: values[i] }))
    .sort((a, b) => b.pct - a.pct)
    .map(r => `
      <div class="rider" title="${r.label} · ${fmtNum(r.value, 1)} עליות ביום">
        <span class="rider-lbl">${r.label}</span>
        <span class="rider-track"><span class="rider-fill" style="width:${r.pct.toFixed(1)}%"></span></span>
        <span class="rider-pct">${r.pct.toFixed(0)}%</span>
      </div>`).join('');
  return `<div class="riders">${rows}</div>`;
}

function tile(value, label, accent) {
  return `<div class="stop-tile"><div class="stop-tile-val" ${accent ? `style="color:${accent}"` : ''}>${value}</div>
          <div class="stop-tile-lbl">${label}</div></div>`;
}

function renderPanel() {
  const panel = document.getElementById('stopPanel');
  if (!panel || !SS.data) return;
  const s = SS.selected;
  panel.style.display = 'block';
  panel.scrollTop = 0;

  if (!s) { panel.innerHTML = cityPanelHtml(); bindPanel(); return; }

  const bands = SS.data.bands;
  const surveyed = s.boardings_day != null;
  const peakBand = surveyed ? bands[s.boardings_by_band.indexOf(Math.max(...s.boardings_by_band))] : null;
  const address = [s.street, s.house || ''].filter(Boolean).join(' ');

  panel.innerHTML = `
    <div class="stop-head">
      <button class="stop-close" title="סגירה">✕</button>
      <div class="stop-title">${s.name}</div>
      <div class="stop-sub">מק״ט ${s.code} · ${s.routes.length || s.routes_reported || 0} קווים${address ? ' · ' + address : ''}</div>
    </div>

    <div class="stop-tiles">
      ${tile(fmtNum(s.departures_day), 'עצירות מתוזמנות ביום')}
      ${tile(surveyed ? fmtNum(s.boardings_day) : '—', 'עליות ביום', 'var(--primary)')}
      ${tile(s.transfer_pct != null ? s.transfer_pct.toFixed(0) + '%' : '—', '% נסיעות מעבר')}
      ${tile(fmtNum(s.routes.length || s.routes_reported), 'קווים')}
    </div>

    ${s.routes.length ? `
      <div class="stop-sec">קווים בתחנה</div>
      <div class="stop-chips">${s.routes.map(r => `<span class="chip">${r}</span>`).join('')}</div>` : ''}

    ${surveyed ? `
      <div class="stop-sec">עליות לתחנה לפי שעה</div>
      ${bandChart(bands, s.boardings_by_band, 'עליות')}

      <div class="stop-sec">פילוח נוסעים</div>
      ${riderChart(SS.data.rider_types, s.riders)}

      <div class="stop-tiles">
        ${tile(s.trips_to_dest != null ? s.trips_to_dest.toFixed(2) : '—', 'נסיעות ממוצע ליעד')}
        ${tile(peakBand, 'שעת שיא', 'var(--primary)')}
      </div>` : `
      <div class="stop-empty">התחנה לא נכללה בסקר העליות — מוצגות רק העצירות המתוזמנות והקווים מתוך ה-GTFS.</div>`}

    <div class="stop-foot"><button class="stop-link" data-view="city">↩ סקירת כל התחנות</button></div>
    <div class="stop-src">${SS.data.source}</div>`;

  bindPanel();
}

// City-wide (or neighbourhood-wide, when one is selected) roll-up. Summed here from
// the same station records the map is drawing, so the headline and the dots can't
// disagree — and it follows the area filter for free.
function cityPanelHtml() {
  const surveyed = SS.visible.filter(s => s.boardings_day != null);
  const bandTotals = SS.data.bands.map((_, i) =>
    surveyed.reduce((a, s) => a + (s.boardings_by_band ? s.boardings_by_band[i] : 0), 0));
  const riderTotals = SS.data.rider_types.map((_, i) =>
    surveyed.reduce((a, s) => a + (s.riders ? s.riders[i] : 0), 0));
  const boardings = surveyed.reduce((a, s) => a + s.boardings_day, 0);
  const scope = state.areaFilter ? 'בשכונה הנבחרת' : 'ברחבי העיר';
  const top = [...surveyed].sort((a, b) => b.boardings_day - a.boardings_day).slice(0, 5);

  return `
    <div class="stop-head">
      <button class="stop-close" title="סגירה">✕</button>
      <div class="stop-title">סקירת תחנות · ${scope}</div>
      <div class="stop-sub">${fmtNum(SS.visible.length)} תחנות · ${fmtNum(surveyed.length)} עם נתוני סקר</div>
    </div>

    <div class="stop-tiles">
      ${tile(fmtNum(boardings), 'עליות ביום', 'var(--primary)')}
      ${tile(fmtNum(surveyed.reduce((a, s) => a + (s.departures_day || 0), 0)), 'עצירות ביום')}
    </div>

    <div class="stop-sec">עליות לפי שעה</div>
    ${bandChart(SS.data.bands, bandTotals, 'עליות')}

    <div class="stop-sec">פילוח נוסעים</div>
    ${riderChart(SS.data.rider_types, riderTotals)}

    <div class="stop-sec">התחנות העמוסות ביותר</div>
    <div class="stop-top">
      ${top.map(s => `
        <button class="stop-top-row" data-code="${stopKey(s)}">
          <span class="stop-top-name">${s.name}</span>
          <span class="stop-top-val">${fmtNum(s.boardings_day)}</span>
        </button>`).join('')}
    </div>
    <div class="stop-src">${SS.data.source}</div>`;
}

function bindPanel() {
  const panel = document.getElementById('stopPanel');
  panel.querySelector('.stop-close').onclick = closeStopPanel;
  const link = panel.querySelector('.stop-link');
  if (link) link.onclick = () => { SS.selected = null; highlightSelected(); renderPanel(); };
  panel.querySelectorAll('.stop-top-row').forEach(btn => {
    btn.onclick = () => {
      const s = SS.visible.find(x => stopKey(x) === btn.dataset.code);
      if (s) { selectStop(s); map.setView([s.lat, s.lon], Math.max(map.getZoom(), 16)); }
    };
  });
}

// ── Top KPI tile ──────────────────────────────────────────────────────────────

// Reads the neighbourhood's own pre-computed `transit` block when one is selected,
// and the city total from kpis.json otherwise — both produced by the same pipeline
// summary function, so the tile matches the panel roll-up.
function updateStopsKpi(neigh) {
  const val = document.getElementById('kBoard');
  const sub = document.getElementById('kBoardD');
  if (!val) return;

  const cityTotal = D.stopTotals ? D.stopTotals.boardings_day : null;
  if (neigh && neigh.transit) {
    val.textContent = fmtNum(neigh.transit.boardings_day);
    sub.textContent = `${fmtNum(neigh.transit.surveyed)} תחנות · ${neigh.name}`;
  } else if (neigh) {
    val.textContent = '—';
    sub.textContent = `אין תחנות מסוקרות ב${neigh.name}`;
  } else if (cityTotal != null) {
    val.textContent = fmtNum(cityTotal);
    sub.textContent = `${fmtNum(D.stopTotals.surveyed)} תחנות מסוקרות · כל העיר`;
  }
}

// ── Setup ─────────────────────────────────────────────────────────────────────

function injectStopPanel() {
  // Anchored to #map, not #mapwrap — the KPI strip is a sibling of the map, and
  // the panel must never sit on top of the headline figures.
  const wrap = document.getElementById('map');
  if (!wrap) return;
  const panel = document.createElement('div');
  panel.id = 'stopPanel';
  panel.dir = 'rtl';
  wrap.appendChild(panel);

  const style = document.createElement('style');
  style.textContent = `
    #stopPanel {
      position:absolute; left:12px; top:12px; z-index:900; display:none;
      width:296px; max-height:calc(100% - 24px); overflow-y:auto;
      overscroll-behavior:contain;
      background:var(--overlay);
      border:1px solid var(--line); border-radius:var(--radius); padding:12px;
      color:var(--ink); font-family:var(--font-sans); box-shadow:var(--shadow);
    }
    .stop-head { position:relative; margin-bottom:10px }
    .stop-close {
      position:absolute; inset-inline-end:0; top:-2px;
      background:none; border:none; color:var(--ink3); cursor:pointer; font-size:14px;
    }
    .stop-close:hover { color:var(--ink) }
    .stop-title {
      font-family:var(--font-head); font-weight:600; font-size:14.5px;
      padding-inline-end:22px; line-height:1.3;
    }
    .stop-sub { font-size:11px; color:var(--ink3); margin-top:3px }

    .stop-tiles { display:grid; grid-template-columns:1fr 1fr; gap:6px; margin:10px 0 }
    .stop-tile {
      background:var(--panel2); border:1px solid var(--line);
      border-radius:var(--radius-sm); padding:8px 10px;
    }
    .stop-tile-val {
      font-family:var(--font-num); font-size:18px; font-weight:600;
      color:var(--ink); font-variant-numeric:tabular-nums; line-height:1.2;
    }
    .stop-tile-lbl { font-size:10px; color:var(--ink3); margin-top:1px }

    .stop-sec {
      font-size:10px; color:var(--ink3); margin:13px 0 6px;
      font-weight:600; letter-spacing:.08em; text-transform:uppercase;
    }
    .stop-chips { display:flex; flex-wrap:wrap; gap:4px }
    .chip {
      font-family:var(--font-num); font-size:11px; padding:2px 7px;
      border-radius:4px; background:var(--panel2); border:1px solid var(--line);
      font-variant-numeric:tabular-nums;
    }

    .bands { display:flex; gap:2px; align-items:flex-end }
    .band { flex:1; text-align:center; cursor:default }
    .band-val {
      font-family:var(--font-num); font-size:9.5px; color:var(--ink3);
      margin-bottom:3px; font-variant-numeric:tabular-nums;
    }
    .band-bar { border-radius:3px 3px 0 0 }
    .band.peak .band-val { color:var(--ink); font-weight:600 }
    .band-lbl { font-size:8.5px; color:var(--ink3); margin-top:4px; letter-spacing:-.3px }

    .riders { display:flex; flex-direction:column; gap:4px }
    .rider { display:flex; align-items:center; gap:7px; font-size:11px }
    .rider-lbl { width:52px; color:var(--ink2); text-align:start }
    .rider-track { flex:1; height:6px; border-radius:3px; background:var(--panel2); overflow:hidden }
    .rider-fill { display:block; height:100%; border-radius:3px; background:var(--primary) }
    .rider-pct {
      width:30px; text-align:end; font-family:var(--font-num);
      color:var(--ink2); font-variant-numeric:tabular-nums;
    }

    .stop-top { display:flex; flex-direction:column; gap:3px }
    .stop-top-row {
      display:flex; justify-content:space-between; gap:8px; width:100%;
      background:var(--panel2); border:1px solid var(--line); border-radius:var(--radius-sm);
      padding:5px 8px; color:var(--ink); font-family:var(--font-sans);
      font-size:11px; cursor:pointer; text-align:start;
    }
    .stop-top-row:hover { border-color:var(--primary) }
    .stop-top-name { overflow:hidden; text-overflow:ellipsis; white-space:nowrap }
    .stop-top-val {
      font-family:var(--font-num); color:var(--ink2);
      font-variant-numeric:tabular-nums; flex:0 0 auto;
    }

    .stop-empty {
      font-size:11px; color:var(--ink2); line-height:1.6; padding:8px;
      background:var(--panel2); border:1px solid var(--line); border-radius:var(--radius-sm);
    }
    .stop-foot { margin-top:12px }
    .stop-link {
      width:100%; background:var(--panel2); border:1px solid var(--line);
      border-radius:var(--radius-sm); padding:6px;
      color:var(--ink2); font-family:var(--font-sans); font-size:11px; cursor:pointer;
    }
    .stop-link:hover { border-color:var(--primary); color:var(--ink) }
    .stop-src { font-size:9.5px; color:var(--ink3); margin-top:10px; text-align:center }

    #stopsLegend { margin-top:8px }
    .stops-legend-title { font-size:10px; color:var(--ink3); margin-bottom:5px }
    .stops-legend-note { font-size:9.5px; color:var(--ink3); margin-top:4px }
    #stopsLegend .lg-hollow {
      display:inline-block; background:transparent !important;
      border:1.5px solid var(--ink3); box-sizing:border-box;
    }
  `;
  document.head.appendChild(style);
}

injectStopPanel();

// Re-render on theme change so the ramp is picked for the surface in use, and on
// neighbourhood change so both the dots and the roll-up follow the selection.
function refreshStops(neigh) {
  if (SS.data) {
    renderStops();
    if (document.getElementById('stopPanel').style.display === 'block') renderPanel();
  }
  updateStopsKpi(neigh);
}
